  works: [{ title: "Pages of Life", note: "First poetry collection" }, { title: "In the Days of Parting", note: "Cycle of poems" }, { title: "People Close to My Heart", note: "Poems" }, { title: "Reflections", note: "Poems" }, { title: "The Sunlit Pen", note: "Narrative poem dedicated to Hamid Olimjon" }],
  quote: null,
