  works: [{ title: "National anthem of the Republic of Uzbekistan", note: "Words" }, { title: "Little Star", note: "Poems" }, { title: "Mother", note: "Poems" }, { title: "Wonder", note: "Poems" }, { title: "The Road to Paradise", note: "Narrative poem" }, { title: "Inferno (translation)", note: "From Dante's “Divine Comedy”" }],
  quote: { text: "Sunny, free land, happiness and salvation to the people.", src: "National anthem of Uzbekistan" },
