  works: [{ title: "Adibi avval", note: "Primer and reader" }, { title: "Adibi soniy", note: "Second reader" }, { title: "Yer yuzi (The Face of the Earth)", note: "Geography textbook" }, { title: "Khurshid", note: "Newspaper" }],
  quote: null,
